Translate("frFR", "gnomeregan", {
	title = "Gnomeregan",
	aliases = { "cité de Gnomeregan" },
	sections = {
		{
			title = "Résumé",
			text = [=[Gnomeregan était la cité des {link:gnomes}gnomes{/link}, une merveille du monde bâtie dans les collines occidentales de {link:dun-morogh}Dun Morogh{/link}. Ses salles étaient pleines de grands engins, de serviteurs mécaniques et d'appareils qu'aucun autre peuple n'aurait pu imaginer. C'est aujourd'hui une ruine empoisonnée. Ses portes sont gardées par les survivants malades et déments de sa chute, ses profondeurs grouillent de {link:troggs}troggs{/link} et de limon vivant, et en son cœur siège le gnome qui l'a trahie.]=],
		},
		{
			title = "Origines",
			text = [=[Les gnomes bâtirent Gnomeregan de leurs propres mains, en voisins et amis des {link:dwarves}nains{/link} d'{link:ironforge}Ironforge{/link}. Aucune chronique ne donne l'année de sa fondation. Pendant des générations, elle fut le siège du Grand Artisan et la fierté du peuple {link:gnomes}gnome{/link}, et de ses ateliers sortirent bien des machines qui servirent l'{link:alliance}Alliance{/link} pendant la {link:second-war}Deuxième Guerre{/link}.]=],
		},
		{
			title = "La chute",
			text = [=[Les troggs montèrent des profondeurs sous la cité, si nombreux que les gnomes ne purent les contenir. Le Grand Artisan {link:gelbin-mekkatorque}Gelbin Mekkatorque{/link} choisit de les purger avec une arme de fabrication {link:gnomes}gnome{/link}. Elle tua les troggs, mais elle tua aussi un très grand nombre de gnomes, et elle laissa la cité noyée de poison. Beaucoup de ceux qui survécurent devinrent des lépreux, malades de corps et vides d'esprit. Les autres s'enfuirent à {link:ironforge}Ironforge{/link}. Derrière eux, le mekgénieur {link:mekgineer-thermaplugg}Thermaplugg{/link}, à qui le Grand Artisan avait fait confiance, prit la cité pour lui-même.]=],
		},
		{
			title = "Entre les murs",
			text = [=[• {b}L'entrée.{/b} Une {link:gnomes}gnome{/link} nommée Emi Shortfuse tient les portes contre les troggs, avec des explosifs et très peu de patience.
• {b}La zone propre.{/b} Une poignée de gnomes résistants s'accroche à une salle épargnée par le poison, où une étrange machine appelée Sparklematic 5200 nettoie et emballe encore tout ce qu'on y met.
• {b}Les profondeurs.{/b} Des limons empoisonnés, des machines brisées et un robot devenu fou, nommé Techbot, errent dans les salles inférieures. Il fut autrefois l'assistant des bricoleurs. Une étincelle inversa son esprit.
• {b}Les maîtres.{/b} {link:grubbis}Grubbis{/link} mène les troggs dans la cité. {link:mekgineer-thermaplugg}Thermaplugg{/link} commande les gnomes lépreux et les machines. Des nains {link:dark-iron-dwarves}Sombrefer{/link} circulent librement parmi eux, et l'on trouve parfois un émissaire Sombrefer dans les salles.]=],
		},
		{
			title = "Boss",
			text = [=[• {b}{link:grubbis}Grubbis{/link}{/b}, chef des troggs de Gnomeregan.
• {b}{link:viscous-fallout}Viscous Fallout{/link}{/b}, une masse vivante du poison de la cité.
• {b}{link:electrocutioner-6000}Electrocutioner 6000{/link}{/b}, une machine de guerre qui garde toujours son poste.
• {b}{link:crowd-pummeler-9-60}Crowd Pummeler 9-60{/link}{/b}, une énorme brute mécanique.
• {b}{link:dark-iron-ambassador}Ambassadeur Sombrefer{/link}{/b}, un émissaire des {link:dark-iron-dwarves}Sombrefer{/link} qui n'est pas toujours présent.
• {b}{link:mekgineer-thermaplugg}Mekgénieur Thermaplugg{/link}{/b}, le traître qui règne sur les ruines.]=],
		},
		{
			title = "De nos jours",
			text = [=[Les {link:gnomeregan-exiles}exilés de Gnomeregan{/link} n'ont pas oublié leur cité. Depuis {link:tinker-town}Tinker Town{/link}, ils renvoient des volontaires franchir ses portes pour sauver des archives perdues, récupérer des pièces et récupérer les machines laissées derrière eux. À {link:kharanos}Kharanos{/link}, deux gnomes recueillent le poison de la cité dans l'espoir d'un remède. Et les gobelins de la {link:horde}Horde{/link} ont appris que {link:mekgineer-thermaplugg}Thermaplugg{/link} construit une grande machine, un engin meilleur que tous les leurs, et ils en veulent les plans.]=],
		},
	},
})

Translate("frFR", "mekgineer-thermaplugg", {
	title = "Mekgénieur Thermaplugg",
	subtitle = "Le traître de Gnomeregan",
	found = "La salle la plus profonde de Gnomeregan",
	allegiance = "Lui-même",
	aliases = { "Thermaplugg", "Sicco Thermaplugg" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le mekgénieur Sicco Thermaplugg fut jadis l'un des gnomes les plus estimés de {link:gnomeregan}Gnomeregan{/link}. Le Grand Artisan {link:gelbin-mekkatorque}Gelbin Mekkatorque{/link} comptait sur lui. Quand la cité tomba, Thermaplugg ne s'enfuit pas avec son peuple. Il resta, et il se fit le maître des ruines. Les gnomes de {link:tinker-town}Tinker Town{/link} prononcent son nom comme les nains prononcent celui des {link:dark-iron-dwarves}Sombrefer{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Thermaplugg est la raison pour laquelle la chute de {link:gnomeregan}Gnomeregan{/link} reste dans les mémoires comme une trahison, et pas seulement comme un désastre. Sa perfidie a fait d'une catastrophe une blessure que les gnomes ne peuvent laisser se refermer. Tant qu'il tiendra la cité, elle ne pourra être reprise.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il trahit le Grand Artisan et le peuple {link:gnomes}gnome{/link} lors de la chute de {link:gnomeregan}Gnomeregan{/link}.
• Il règne sur la cité empoisonnée avec une armée de gnomes lépreux, de troggs et de machines de guerre.
• Il traite avec les nains {link:dark-iron-dwarves}Sombrefer{/link}, qui circulent librement dans ses salles et aident à ses travaux.
• Il construit un grand engin d'un modèle nouveau, dont les plans reposent dans un coffre-fort près de son trône.]=],
		},
		{
			title = "Le roi de rien",
			text = [=[Ce que voulait Thermaplugg, {link:gelbin-mekkatorque}Mekkatorque{/link} ne peut toujours pas le dire. Le pouvoir, peut-être, ou la richesse. L'un et l'autre lui seraient venus avec le temps, s'il avait seulement attendu. Il choisit plutôt un trône dans une ruine, entouré des restes déments du peuple qu'il servait autrefois. Le Grand Artisan l'appelle le roi de rien. Pourtant, le traître n'est pas oisif. Ses machines bourdonnent encore dans les profondeurs, et les gobelins de la {link:horde}Horde{/link} murmurent que son nouvel engin surpasse tous les déchiqueteurs qu'ils aient jamais construits. Un {link:gnomes}gnome{/link} captif qui s'échappa de ses salles jura que les {link:dark-iron-dwarves}Sombrefer{/link} avaient pris part à sa fabrication.]=],
		},
		{
			title = "Non consigné",
			text = [=[On sait peu de chose de la vie de Thermaplugg avant la chute, ni de la façon dont il gagna à ce point la confiance du Grand Artisan.]=],
		},
	},
	chapters = {
		{
			title = "La grande trahison",
			hint = [=[Portez le jugement du Grand Artisan jusqu'au cœur de Gnomeregan.]=],
			text = [=[{link:gelbin-mekkatorque}Mekkatorque{/link} ne demandait qu'une chose à ceux qui voulaient se battre pour {link:gnomeregan}Gnomeregan{/link} : qu'ils tuent le traître. Quand ce fut fait, le Grand Artisan dit espérer que la dernière chose que Thermaplugg ait jamais sentie fut une botte. Puis il parla de ce qui comptait vraiment. Le traître disparu, les gnomes étaient un pas plus près de rentrer chez eux.]=],
		},
		{
			title = "L'engin",
			hint = "Prenez ce que Thermaplugg a enfermé près de son trône.",
			text = [=[Les plans de l'engin reposaient dans un coffre-fort près de Thermaplugg, et lui seul en connaissait la combinaison. L'ingénieur gobelin Nogg, d'{link:orgrimmar}Orgrimmar{/link}, les voulait au point d'envoyer des inconnus dans la salle la plus profonde de {link:gnomeregan}Gnomeregan{/link}. Là où va l'ingéniosité {link:gnomes}gnome{/link}, le profit gobelin suit.]=],
		},
	},
	mentions = {
		{ text = "Un beau gâchis" },
		{ text = "La guerre des engins" },
	},
	bonds = {
		{ id = "gelbin-mekkatorque", name = "Gelbin Mekkatorque", note = "le Grand Artisan qu'il a trahi" },
		{ id = "grubbis", name = "Grubbis", note = "mène les troggs de sa cité" },
		{ id = "dark-iron-ambassador", name = "Ambassadeur Sombrefer", note = "un émissaire de ses alliés" },
	},
})

Translate("frFR", "grubbis", {
	title = "Grubbis",
	subtitle = "Chef des troggs de Gnomeregan",
	found = "Les salles extérieures de Gnomeregan, près de l'entrée",
	allegiance = "Troggs de Gnomeregan",
	sections = {
		{
			title = "Résumé",
			text = [=[Grubbis est le chef {link:troggs}trogg{/link} qui mène les siens dans les salles de {link:gnomeregan}Gnomeregan{/link}. Il ne combat pas seul. Une grande bête nommée Chomper le suit au combat. Quand la {link:gnomes}gnome{/link} Emi Shortfuse pose ses charges pour sceller les tunnels près des portes de la cité, ce sont Grubbis et ses guerriers qui surgissent des ténèbres pour l'en empêcher.]=],
		},
		{
			title = "Importance",
			text = [=[Grubbis est le visage de l'invasion {link:troggs}trogg{/link} qui brisa {link:gnomeregan}Gnomeregan{/link}. La purge des gnomes n'a pas détruit son peuple ; elle l'a seulement rendu plus étrange.]=],
		},
	},
	bonds = {
		{ id = "mekgineer-thermaplugg", name = "Mekgénieur Thermaplugg", note = "partage les ruines avec lui" },
	},
})

Translate("frFR", "viscous-fallout", {
	title = "Viscous Fallout",
	subtitle = "Le poison vivant",
	found = "Les profondeurs empoisonnées de Gnomeregan",
	allegiance = "Aucune",
	sections = {
		{
			title = "Résumé",
			text = [=[Viscous Fallout est ce que la purge de {link:gnomeregan}Gnomeregan{/link} a laissé derrière elle. C'est une masse palpitante de limon vert, née du poison qui inonda la cité, et elle rôde dans les profondeurs où le poison est le plus épais. De plus petits limons et des horreurs rampent autour d'elle. Les gnomes qui étudient le poison à {link:kharanos}Kharanos{/link} veulent des échantillons de telles créatures, prélevés frais, car ils disent que les retombées des troggs sont trop faibles pour leurs travaux.]=],
		},
		{
			title = "Importance",
			text = [=[Viscous Fallout est l'arme des gnomes eux-mêmes, devenue chair. C'est le seul ennemi de {link:gnomeregan}Gnomeregan{/link} dont personne d'autre ne peut être tenu pour responsable.]=],
		},
	},
})

Translate("frFR", "electrocutioner-6000", {
	title = "Electrocutioner 6000",
	subtitle = "Machine gardienne de Gnomeregan",
	found = "Les salles de Gnomeregan",
	allegiance = "Machines de Gnomeregan",
	sections = {
		{
			title = "Résumé",
			text = [=[Electrocutioner 6000 est une grande machine de guerre de {link:gnomeregan}Gnomeregan{/link}, armée de la foudre. Elle fut construite pour garder la cité. Ses créateurs ont disparu, ou sont empoisonnés, ou en exil, mais la machine se tient toujours à son poste et foudroie quiconque approche.]=],
		},
		{
			title = "Importance",
			text = [=[L'Electrocutioner montre le côté amer du génie {link:gnomes}gnome{/link}. Les défenses de la cité étaient trop bien faites, et désormais elles la défendent contre son propre peuple.]=],
		},
	},
})

Translate("frFR", "crowd-pummeler-9-60", {
	title = "Crowd Pummeler 9-60",
	subtitle = "Brute mécanique",
	found = "Une grande salle de Gnomeregan",
	allegiance = "Machines de Gnomeregan",
	sections = {
		{
			title = "Résumé",
			text = [=[Crowd Pummeler 9-60 est une énorme machine de {link:gnomeregan}Gnomeregan{/link}, construite, comme son nom s'en vante, pour mater les foules. Elle piétine et frappe encore dans l'une des grandes salles de la cité, comme si ses créateurs la regardaient. Que les gnomes l'aient construite pour le jeu, pour la guerre ou pour maintenir l'ordre dans leurs rues, aucun survivant n'a pris la peine de le dire.]=],
		},
		{
			title = "Importance",
			text = [=[Comme une grande part de ce que les gnomes ont laissé derrière eux, le Pummeler a survécu à sa raison d'être et gardé sa force.]=],
		},
	},
})

Translate("frFR", "dark-iron-ambassador", {
	title = "Ambassadeur Sombrefer",
	subtitle = "Émissaire des Sombrefer",
	found = "Les salles de Gnomeregan (pas toujours présent)",
	allegiance = "Nains Sombrefer",
	sections = {
		{
			title = "Résumé",
			text = [=[L'Ambassadeur Sombrefer est un émissaire des {link:dark-iron-dwarves}Sombrefer{/link}, que l'on trouve parfois dans les salles de {link:gnomeregan}Gnomeregan{/link}, gardé par le feu. Quelles affaires les Sombrefer ont avec {link:mekgineer-thermaplugg}Thermaplugg{/link}, cela n'est écrit nulle part. Pourtant, les signes sont nombreux : un {link:gnomes}gnome{/link} captif battu par des nains Sombrefer, la bague d'un joaillier gnome trouvée sur un cadavre Sombrefer, et un nouvel engin construit avec l'aide des Sombrefer.]=],
		},
		{
			title = "Importance",
			text = [=[L'Ambassadeur est la preuve que la ruine de {link:gnomeregan}Gnomeregan{/link} fait partie d'une toile plus vaste, et que le vieil ennemi d'{link:ironforge}Ironforge{/link} a étendu la main jusque dans la cité des gnomes.]=],
		},
	},
	bonds = {
		{ id = "mekgineer-thermaplugg", name = "Mekgénieur Thermaplugg", note = "le traître avec qui il traite" },
	},
})
